//! The per-launch token and its owner-only file.
//!
//! The token is 32 random bytes rendered as lowercase hex. It is generated by the daemon at every
//! start, written before the endpoint accepts a client, and overwritten on the next start. A client
//! reads the file; a stale file therefore fails the handshake instead of authenticating.

use std::fmt;
use std::fs::OpenOptions;
use std::io::{Read as _, Write as _};
use std::path::{Path, PathBuf};

use zeroize::Zeroizing;

use crate::{IpcError, platform};

/// A shared secret. `Debug` and `Display` are redacted; only the handshake and the token file see
/// the bytes.
#[derive(Clone, PartialEq, Eq)]
pub struct SharedToken(Zeroizing<String>);

impl SharedToken {
    pub fn generate() -> Result<Self, IpcError> {
        let mut bytes = [0u8; 32];
        getrandom::fill(&mut bytes)?;
        Ok(Self(Zeroizing::new(hex(&bytes))))
    }

    pub fn from_hex(value: &str) -> Result<Self, IpcError> {
        let value = value.trim();
        if value.len() != 64 || !value.bytes().all(|byte| byte.is_ascii_hexdigit()) {
            return Err(IpcError::TokenFile("the token is not 64 hexadecimal characters".to_owned()));
        }
        Ok(Self(Zeroizing::new(value.to_ascii_lowercase())))
    }

    /// Constant-time comparison: a wrong token must not leak its first differing byte.
    pub fn verify(&self, candidate: &str) -> bool {
        let expected = self.0.as_bytes();
        let actual = candidate.as_bytes();
        if expected.len() != actual.len() {
            return false;
        }
        let mut difference = 0u8;
        for (left, right) in expected.iter().zip(actual.iter()) {
            difference |= left ^ right;
        }
        difference == 0
    }

    pub(crate) fn as_str(&self) -> &str {
        self.0.as_str()
    }
}

impl fmt::Debug for SharedToken {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("SharedToken(redacted)")
    }
}

impl fmt::Display for SharedToken {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.write_str("[redacted]")
    }
}

fn hex(bytes: &[u8]) -> String {
    const DIGITS: &[u8; 16] = b"0123456789abcdef";
    let mut out = String::with_capacity(bytes.len() * 2);
    for byte in bytes {
        out.push(char::from(*DIGITS.get(usize::from(byte >> 4)).unwrap_or(&b'0')));
        out.push(char::from(*DIGITS.get(usize::from(byte & 0x0f)).unwrap_or(&b'0')));
    }
    out
}

/// The owner-only token file. It lives next to the store (`mail.db.token`) so two stores in one
/// directory never share a token.
pub struct TokenFile {
    path: PathBuf,
}

impl TokenFile {
    pub fn new(path: impl Into<PathBuf>) -> Self {
        Self { path: path.into() }
    }

    pub fn path(&self) -> &Path {
        &self.path
    }

    /// Replace the token atomically. The caller is the daemon, which holds the store's writer lock;
    /// clients that race a rotation see "daemon not running" and reconnect.
    pub fn write(&self, token: &SharedToken) -> Result<(), IpcError> {
        let parent = self.path.parent().filter(|parent| !parent.as_os_str().is_empty());
        if let Some(parent) = parent {
            std::fs::create_dir_all(parent).map_err(|error| IpcError::TokenFile(format!("creating {}: {error}", parent.display())))?;
        }
        let mut random = [0u8; 8];
        getrandom::fill(&mut random)?;
        let temporary = self.path.with_extension(format!("token-tmp-{}", hex(&random)));
        let mut options = OpenOptions::new();
        options.write(true).create_new(true);
        #[cfg(unix)]
        {
            use std::os::unix::fs::OpenOptionsExt as _;
            options.mode(0o600);
        }
        let mut file = options.open(&temporary).map_err(|error| IpcError::TokenFile(format!("creating the token file: {error}")))?;
        if let Err(error) = file.write_all(token.as_str().as_bytes()).and_then(|()| file.write_all(b"\n")).and_then(|()| file.sync_all()) {
            let _ = std::fs::remove_file(&temporary);
            return Err(IpcError::TokenFile(format!("writing the token file: {error}")));
        }
        drop(file);
        if let Err(error) = platform::harden_owner_only(&temporary) {
            let _ = std::fs::remove_file(&temporary);
            return Err(IpcError::TokenFile(format!("setting token file permissions: {error}")));
        }
        // `rename` replaces atomically on Unix; on Windows `MoveFileExW` replaces the destination
        // without a missing-file window. The daemon holds the writer lock, so no other writer owns
        // this file.
        #[cfg(windows)]
        let published = platform::replace_file(&temporary, &self.path);
        #[cfg(not(windows))]
        let published = std::fs::rename(&temporary, &self.path);
        if let Err(error) = published {
            let _ = std::fs::remove_file(&temporary);
            return Err(IpcError::TokenFile(format!("publishing the token file: {error}")));
        }
        // A second harden after the rename covers a filesystem that does not preserve the temp
        // file's ACL when moving it within the same directory.
        platform::harden_owner_only(&self.path).map_err(|error| IpcError::TokenFile(format!("setting token file permissions: {error}")))?;
        Ok(())
    }

    /// Read the token. On Unix an insecure mode is refused instead of used; on Windows the ACL is
    /// set by [`TokenFile::write`] and the directory is the per-user data directory.
    pub fn read(&self) -> Result<SharedToken, IpcError> {
        let metadata = std::fs::symlink_metadata(&self.path).map_err(|error| IpcError::TokenFile(format!("reading the token file: {error}")))?;
        if !metadata.file_type().is_file() {
            return Err(IpcError::TokenFile("the token path is not a regular file".to_owned()));
        }
        if metadata.len() > 256 {
            return Err(IpcError::TokenFile("the token file is larger than a token".to_owned()));
        }
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            let mode = metadata.permissions().mode() & 0o777;
            if mode & 0o077 != 0 {
                return Err(IpcError::InsecureTokenFile(format!("mode {mode:o} is not 0600")));
            }
        }
        #[cfg(windows)]
        {
            let owner_only =
                platform::acl_is_owner_only(&self.path).map_err(|error| IpcError::TokenFile(format!("reading the token ACL: {error}")))?;
            if !owner_only {
                return Err(IpcError::InsecureTokenFile("the DACL is not one ACE for the current user".to_owned()));
            }
        }
        let file = std::fs::File::open(&self.path).map_err(|error| IpcError::TokenFile(format!("reading the token file: {error}")))?;
        let mut raw = Vec::with_capacity(usize::try_from(metadata.len()).unwrap_or(256).min(256));
        let mut limited = file.take(257);
        limited.read_to_end(&mut raw).map_err(|error| IpcError::TokenFile(format!("reading the token file: {error}")))?;
        if raw.len() > 256 {
            return Err(IpcError::TokenFile("the token file is larger than a token".to_owned()));
        }
        let text = String::from_utf8(raw).map_err(|_| IpcError::TokenFile("the token file is not UTF-8".to_owned()))?;
        SharedToken::from_hex(&text)
    }

    pub fn remove(&self) {
        let _ = std::fs::remove_file(&self.path);
    }
}

impl fmt::Debug for TokenFile {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        formatter.debug_struct("TokenFile").field("path", &self.path).finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn a_token_round_trips_and_verifies_in_constant_time_shape() {
        let token = SharedToken::generate().expect("token");
        let text = token.as_str().to_owned();
        assert_eq!(text.len(), 64);
        assert!(token.verify(&text));
        assert!(!token.verify(&text.to_ascii_uppercase()));
        assert!(!token.verify("short"));
        assert_eq!(format!("{token}"), "[redacted]");
        assert_eq!(format!("{token:?}"), "SharedToken(redacted)");
    }

    #[test]
    fn the_file_is_owner_only_and_a_new_token_replaces_the_old_one() {
        let dir = tempfile::tempdir().expect("tempdir");
        let file = TokenFile::new(dir.path().join("mail.db.token"));
        let first = SharedToken::generate().expect("token");
        file.write(&first).expect("write");
        assert_eq!(file.read().expect("read"), first);
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            let mode = std::fs::metadata(file.path()).expect("metadata").permissions().mode() & 0o777;
            assert_eq!(mode, 0o600);
        }
        let second = SharedToken::generate().expect("token");
        file.write(&second).expect("rotate");
        assert_eq!(file.read().expect("read"), second);
        assert!(file.read().expect("read").verify(second.as_str()));
        assert!(!file.read().expect("read").verify(first.as_str()));
    }

    #[cfg(unix)]
    #[test]
    fn an_insecure_token_file_is_refused() {
        use std::os::unix::fs::PermissionsExt as _;
        let dir = tempfile::tempdir().expect("tempdir");
        let file = TokenFile::new(dir.path().join("mail.db.token"));
        file.write(&SharedToken::generate().expect("token")).expect("write");
        std::fs::set_permissions(file.path(), std::fs::Permissions::from_mode(0o644)).expect("chmod");
        assert!(matches!(file.read(), Err(IpcError::InsecureTokenFile(_))));
    }

    #[test]
    fn a_huge_token_file_is_rejected_before_it_is_read() {
        let dir = tempfile::tempdir().expect("tempdir");
        let file = TokenFile::new(dir.path().join("mail.db.token"));
        file.write(&SharedToken::generate().expect("token")).expect("write");
        std::fs::write(file.path(), vec![b'x'; 1024 * 1024]).expect("huge file");
        #[cfg(unix)]
        {
            use std::os::unix::fs::PermissionsExt as _;
            std::fs::set_permissions(file.path(), std::fs::Permissions::from_mode(0o600)).expect("chmod");
        }
        assert!(matches!(file.read(), Err(IpcError::TokenFile(_))));
    }

    #[test]
    fn a_malformed_token_file_is_refused() {
        let dir = tempfile::tempdir().expect("tempdir");
        let file = TokenFile::new(dir.path().join("mail.db.token"));
        file.write(&SharedToken::generate().expect("token")).expect("write");
        std::fs::write(file.path(), b"not-a-token\n").expect("write");
        assert!(matches!(file.read(), Err(IpcError::TokenFile(_))));
    }
}
